    _mask_iou_batch_split,
)


def pack(masks):
    """(N, H, W) bool -> (N, K) uint64 bitsets."""
    n = masks.shape[0]
    packed = np.packbits(masks.reshape(n, int(np.prod(masks.shape[1:]))), axis=1)
    packed = np.pad(packed, ((0, 0), (0, -packed.shape[1] % 8)))
    return np.ascontiguousarray(packed).view(np.uint64)


def overlap(inter, area_a, area_b, metric):
